// Extract the user message
const message = $input.first().json.message;
const text = message.text || '';
const chatId = message.chat.id;

// Pass to AI Agent for classification
return [{ json: { text, chatId, userId: message.from.id } }];

const aiOutput = $input.first().json.output;
try {
  const parsed = JSON.parse(aiOutput);
  return [{ json: { ...parsed, chatId: $('Extract Message').first().json.chatId } }];
} catch (e) {
  return [{ json: { pipeline: 'image', prompt: $('Extract Message').first().json.text, style: 'base', confidence: 0.5, chatId: $('Extract Message').first().json.chatId } }];
}
